/**
 * Ownership handover offers. Every read and write is filtered by `orgId`; rows
 * are resolved in place, never deleted.
 */
import { and, desc, eq, lte, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, ownershipHandovers } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toOwnershipHandover } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type {
  OwnershipHandover,
  OwnershipHandoverStatus,
} from "@/types/organization";

/** The terminal states an open offer can be moved to by someone acting on it. */
export type ResolvedHandoverStatus = Exclude<
  OwnershipHandoverStatus,
  "pending" | "expired"
>;

export async function insertHandover(
  orgId: OrgId,
  fromUserId: UserId,
  toUserId: UserId,
  createdAt: IsoTimestamp,
  expiresAt: IsoTimestamp,
): Promise<OwnershipHandover> {
  const row = getDb()
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId,
      fromUserId,
      toUserId,
      status: "pending",
      expiresAt,
      resolvedAt: null,
      createdAt,
      updatedAt: createdAt,
    })
    .returning()
    .get();

  return toOwnershipHandover(row);
}

/**
 * The organization's pending offer, lapsed or not — the caller decides what a
 * lapsed one means. At most one exists (see the partial unique index).
 */
export async function findPendingHandover(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .orderBy(desc(ownershipHandovers.createdAt))
    .get();
  return row ? toOwnershipHandover(row) : null;
}

/** Moves a pending offer to its final state, stamping when that happened. */
export async function resolveHandover(
  orgId: OrgId,
  handoverId: string,
  status: ResolvedHandoverStatus,
  at: IsoTimestamp,
): Promise<OwnershipHandover> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.id, handoverId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Ownership handover ${handoverId} is not pending`);
  return toOwnershipHandover(row);
}

/**
 * Marks every pending offer whose deadline has passed as `expired`, resolved
 * at the instant it lapsed. Frees the "one pending offer" slot for a new one.
 */
export async function expireLapsedHandovers(
  orgId: OrgId,
  now: IsoTimestamp,
): Promise<number> {
  const result = getDb()
    .update(ownershipHandovers)
    .set({
      status: "expired",
      resolvedAt: ownershipHandovers.expiresAt,
      updatedAt: now,
    })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        lte(ownershipHandovers.expiresAt, now),
      ),
    )
    .run();
  return result.changes;
}

/** Withdraws any pending offer the user makes or receives, e.g. when they leave. */
export async function cancelPendingHandoversInvolving(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<number> {
  const result = getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .run();
  return result.changes;
}
EOF

