/**
 * Offers the workspace to another active member. Only the recorded owner may
 * offer — holding the owner role is not enough — and only one offer may be
 * open at a time; a lapsed one no longer counts. The offered member is the
 * only one alerted.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  assertRecordedOwner(actor, org);

  if (toUserId === org.ownerId) {
    throw new OwnershipHandoverError("self");
  }

  const recipient = await memberRepo.findMember(orgId, toUserId);
  if (!recipient || recipient.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const now = new Date();
  const createdAt = toIsoTimestamp(now);

  await handoverRepo.expireLapsedHandovers(orgId, createdAt);
  if ((await handoverRepo.findPendingHandover(orgId)) !== null) {
    throw new OwnershipHandoverError("pending_exists");
  }

  const handover = await handoverRepo.insertHandover(
    orgId,
    org.ownerId,
    toUserId,
    createdAt,
    toIsoTimestamp(new Date(now.getTime() + HANDOVER_TTL_MS)),
  );

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You were offered ownership of a workspace",
    body: `Accept to become the owner of ${org.name}`,
    href: "/settings",
    actorId: actor.userId,
  });

  return handover;
}

/**
 * The offered member takes the workspace over. The new owner is promoted
 * before the previous one steps down to admin, so the organization holds an
 * owner at every instant and the last-owner rule never trips. Every event is
 * published on behalf of the accepting member.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);

  const now = new Date();
  const handover = await requireOfferTo(actor, orgId, now);

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  const incoming = requireFound(
    await memberRepo.findMember(orgId, actor.userId),
    "Member",
    actor.userId,
  );
  const outgoing = await memberRepo.findMember(orgId, org.ownerId);

  const roleChanges: { memberId: MemberId; from: Role; to: Role }[] = [];

  if (incoming.role !== "owner") {
    await memberRepo.updateMemberRole(orgId, incoming.id, "owner");
    roleChanges.push({ memberId: incoming.id, from: incoming.role, to: "owner" });
  }

  const transferred = await orgRepo.updateOrgOwner(orgId, actor.userId);

  if (outgoing && outgoing.id !== incoming.id && outgoing.role === "owner") {
    await assertLastOwnerRetained(orgId, outgoing.id, "admin");
    await memberRepo.updateMemberRole(orgId, outgoing.id, "admin");
    roleChanges.push({ memberId: outgoing.id, from: "owner", to: "admin" });
  }

  await handoverRepo.resolveHandover(
    orgId,
    handover.id,
    "accepted",
    toIsoTimestamp(now),
  );

  for (const change of roleChanges) {
    await emit("member.role_changed", { ...actorEnvelope(actor), ...change });
  }

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: org.ownerId,
    toUserId: actor.userId,
  });

  return transferred;
}

/** The offered member turns the offer down; the owner may offer again. */
export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const now = new Date();
  const handover = await requireOfferTo(actor, orgId, now);

  return handoverRepo.resolveHandover(
    orgId,
    handover.id,
    "declined",
    toIsoTimestamp(now),
  );
}

/** The recorded owner withdraws their open offer. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  assertRecordedOwner(actor, org);

  const now = new Date();
  const handover = await findOpenHandover(orgId, now);
  if (handover === null) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  return handoverRepo.resolveHandover(
    orgId,
    handover.id,
    "canceled",
    toIsoTimestamp(now),
  );
}

/** The open offer, if any — visible to every member of the workspace. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  return findOpenHandover(orgId, new Date());
}

/**
 * Offering and withdrawing belong to the recorded owner alone. `can()` only
 * knows roles, and a second member holding the owner role must be refused, so
 * this is decided against the organization row instead.
 */
function assertRecordedOwner(actor: Actor, org: Organization): void {
  if (actor.userId === org.ownerId) return;

  throw new PermissionDeniedError("org:transfer_ownership", {
    allowed: false,
    action: "org:transfer_ownership",
    resourceKind: "organization",
    reason: "denied_not_recorded_owner",
  });
}

/** An offer can be acted on before `expiresAt` and no longer from it on. */
function hasLapsed(handover: OwnershipHandover, now: Date): boolean {
  return now.getTime() >= Date.parse(handover.expiresAt);
}

/** The offer as the rest of the app sees it: pending and not yet lapsed. */
async function findOpenHandover(
  orgId: OrgId,
  now: Date,
): Promise<OwnershipHandover | null> {
  const pending = await handoverRepo.findPendingHandover(orgId);
  return pending !== null && !hasLapsed(pending, now) ? pending : null;
}

/**
 * The pending offer addressed to `actor`. Anyone else — and everyone, when
 * nothing is pending — is refused with `nothing_pending`; the addressee of a
 * lapsed offer is told it `expired`.
 */
async function requireOfferTo(
  actor: Actor,
  orgId: OrgId,
  now: Date,
): Promise<OwnershipHandover> {
  const pending = await handoverRepo.findPendingHandover(orgId);

  if (pending === null || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (hasLapsed(pending, now)) {
    throw new OwnershipHandoverError("expired");
  }

  return pending;
}
