    expect(audit.items).toEqual([
      expect.objectContaining({
        action: "organization.ownership_transferred",
        actorId: tenant.userIds.member,
        subjectKind: "organization",
        subjectId: tenant.org.id,
        metadata: { fromUserId: tenant.userIds.owner, toUserId: tenant.userIds.member },
      }),
    ]);

    await expect(
      getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).resolves.toBeNull();
    expect(await refusal(acceptOwnershipHandover(tenant.actors.member, tenant.org.id))).toBe(
      "nothing_pending",
    );
  });

  it("only demotes the previous owner when the new one already held the owner role", async () => {
    const tenant = await createTenant("handover-co-owner");
    const coOwner = await promoteAdminToOwner(tenant);
    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.admin);

    const roleChanges = capture("member.role_changed");
    await acceptOwnershipHandover(coOwner, tenant.org.id);

    expect(roleChanges).toEqual([
      expect.objectContaining({
        memberId: await memberIdOf(tenant, "owner"),
        from: "owner",
        to: "admin",
      }),
    ]);
    expect(await roleOf(tenant, "admin")).toBe("owner");
    expect(await roleOf(tenant, "owner")).toBe("admin");
  });

  it("makes everything that follows the owner follow the new one", async () => {
    const tenant = await createTenant("handover-consequences");
    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.admin);
    await acceptOwnershipHandover(tenant.actors.admin, tenant.org.id);

    const newOwner = await memberService.resolveActor(tenant.userIds.admin, tenant.org.id);
    const previousOwner = await memberService.resolveActor(tenant.userIds.owner, tenant.org.id);
    if (!newOwner || !previousOwner) throw new Error("actors missing");
    expect(previousOwner.role).toBe("admin");

    await emit("member.joined", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.viewer,
      occurredAt: tenant.org.createdAt,
      memberId: await memberIdOf(tenant, "viewer"),
      userId: tenant.userIds.viewer,
      role: "viewer",
    });
    for (const [actor, expected] of [
      [newOwner, 1],
      [previousOwner, 0],
    ] as const) {
      const alerts = await listNotifications(actor, {
        orgId: tenant.org.id,
        recipientId: actor.userId,
        unreadOnly: false,
        kind: ["member_joined"],
        limit: 25,
        cursor: null,
      });
      expect(alerts.total).toBe(expected);
    }

    const plan = { orgId: tenant.org.id, plan: "enterprise", interval: "monthly" } as const;
    for (const stale of [previousOwner, tenant.actors.owner]) {
      await expect(billingService.changePlan(stale, plan)).rejects.toBeInstanceOf(
        PermissionDeniedError,
      );
    }
    await expect(billingService.changePlan(newOwner, plan)).resolves.toMatchObject({
      plan: "enterprise",
    });

    const removed = await memberService.removeMember(newOwner, {
      orgId: tenant.org.id,
      memberId: await memberIdOf(tenant, "owner"),
    });
    expect(removed.archivedAt).not.toBeNull();
  });
});

describe("lapsing", () => {
  it("can be acted on until, but not from, seven days after it was made", async () => {
    const tenant = await createTenant("handover-lapse-edge");
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-05-01T12:00:00.000Z"));

    const handover = await initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );
    const lapsesAt = Date.parse(handover.createdAt) + SEVEN_DAYS_MS;

    vi.setSystemTime(lapsesAt - 1);
    await expect(
      getPendingOwnershipHandover(tenant.actors.admin, tenant.org.id),
    ).resolves.toMatchObject({ id: handover.id });
    await expect(
      acceptOwnershipHandover(tenant.actors.member, tenant.org.id),
    ).resolves.toMatchObject({ ownerId: tenant.userIds.member });
  });

  it("refuses a lapsed offer as expired and stops counting it as open", async () => {
    const tenant = await createTenant("handover-lapse");
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-05-01T12:00:00.000Z"));

    const handover = await initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
