/**
 * Handing a workspace over to another member, with their consent.
 *
 * `organization-service` owns the offer lifecycle; the consequences of an
 * acceptance are pinned through the services that follow "the owner".
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { OwnershipHandoverError, isDomainError, toAppError } from "@/lib/errors";
import { emit, subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { listActivity, registerActivityListeners } from "@/server/services/activity-service";
import * as billingService from "@/server/services/billing-service";
import * as memberService from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import {
  acceptOwnershipHandover,
  cancelOwnershipHandover,
  declineOwnershipHandover,
  getPendingOwnershipHandover,
  initiateOwnershipHandover,
} from "@/server/services/organization-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { OwnershipHandoverRefusal } from "@/lib/errors";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";
import type { Actor, Role } from "@/types/member";

const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000;

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

async function refusal(promise: Promise<unknown>): Promise<OwnershipHandoverRefusal> {
  const error: unknown = await promise.then(
    () => expect.unreachable("expected the handover request to be refused"),
    (thrown: unknown) => thrown,
  );
  expect(error).toBeInstanceOf(OwnershipHandoverError);
  return (error as OwnershipHandoverError).reason;
}

async function roleOf(tenant: Tenant, role: Role): Promise<Role | undefined> {
  return (await memberRepo.findMember(tenant.org.id, tenant.userIds[role]))?.role;
}

async function memberIdOf(tenant: Tenant, role: Role) {
  const member = await memberRepo.findMember(tenant.org.id, tenant.userIds[role]);
  if (!member) throw new Error(`fixture ${role} missing`);
  return member.id;
}

/** The fixture's admin, given the owner role without becoming the recorded owner. */
async function promoteAdminToOwner(tenant: Tenant): Promise<Actor> {
  await memberService.updateMemberRole(tenant.actors.owner, {
    orgId: tenant.org.id,
    memberId: await memberIdOf(tenant, "admin"),
    role: "owner",
  });
  return { ...tenant.actors.admin, role: "owner" };
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  vi.useRealTimers();
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  cleanup();
});

describe("offering the workspace", () => {
  it("opens a seven-day offer and alerts only the offered member", async () => {
    const tenant = await createTenant("handover-offer");
    const offered = capture("member.role_changed");

    const handover = await initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );

    expect(handover).toMatchObject({
      orgId: tenant.org.id,
      fromUserId: tenant.userIds.owner,
      toUserId: tenant.userIds.member,
      status: "pending",
      resolvedAt: null,
    });
    expect(Date.parse(handover.expiresAt) - Date.parse(handover.createdAt)).toBe(
      SEVEN_DAYS_MS,
    );
    expect(offered).toHaveLength(0);

    for (const role of ["owner", "admin", "member", "viewer"] as const) {
      const page = await listNotifications(tenant.actors[role], {
        orgId: tenant.org.id,
        recipientId: tenant.userIds[role],
        unreadOnly: false,
        kind: ["ownership_handover"],
        limit: 25,
        cursor: null,
      });
      expect(page.total, role).toBe(role === "member" ? 1 : 0);
    }

    for (const role of ["owner", "admin", "member", "viewer"] as const) {
      await expect(
        getPendingOwnershipHandover(tenant.actors[role], tenant.org.id),
      ).resolves.toEqual(handover);
    }
  });

  it("is reserved to the recorded owner, not to anyone holding the owner role", async () => {
    const tenant = await createTenant("handover-recorded-owner");
    const coOwner = await promoteAdminToOwner(tenant);

    await expect(
      initiateOwnershipHandover(coOwner, tenant.org.id, tenant.userIds.member),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      initiateOwnershipHandover(tenant.actors.member, tenant.org.id, tenant.userIds.viewer),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member);
    await expect(cancelOwnershipHandover(coOwner, tenant.org.id)).rejects.toBeInstanceOf(
      PermissionDeniedError,
    );
    await expect(
      getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).resolves.not.toBeNull();
  });

  it("must go to another active member of the same workspace", async () => {
    const tenant = await createTenant("handover-target");
    const other = await createTenant("handover-target-other");
    const stranger = await userRepo.insertUser({
      email: "stranger@handover.test",
      name: "Stranger",
      passwordHash: "seed",
    });

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: await memberIdOf(tenant, "viewer"),
    });

    for (const target of [stranger.id, other.userIds.member, tenant.userIds.viewer]) {
      await expect(
        initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, target),
      ).rejects.toBeInstanceOf(NotFoundError);
    }

    expect(
      await refusal(
        initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.owner),
      ),
    ).toBe("self");
    await expect(
      getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).resolves.toBeNull();
  });

  it("allows one open offer at a time, until it is withdrawn", async () => {
    const tenant = await createTenant("handover-single");

    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member);
    expect(
      await refusal(
        initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.admin),
      ),
    ).toBe("pending_exists");

    const withdrawn = await cancelOwnershipHandover(tenant.actors.owner, tenant.org.id);
    expect(withdrawn.status).toBe("canceled");
    expect(withdrawn.resolvedAt).toEqual(expect.any(String));
    await expect(
      getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).resolves.toBeNull();

    expect(await refusal(cancelOwnershipHandover(tenant.actors.owner, tenant.org.id))).toBe(
      "nothing_pending",
    );
    expect(await refusal(declineOwnershipHandover(tenant.actors.member, tenant.org.id))).toBe(
      "nothing_pending",
    );

    const again = await initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.admin,
    );
    expect(again.toUserId).toBe(tenant.userIds.admin);
  });

  it("is invisible and untouchable from another workspace", async () => {
    const tenant = await createTenant("handover-scope");
    const other = await createTenant("handover-scope-other");

    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member);

    await expect(
      getPendingOwnershipHandover(other.actors.owner, other.org.id),
    ).resolves.toBeNull();

    const foreign = [
      initiateOwnershipHandover(other.actors.owner, tenant.org.id, tenant.userIds.admin),
      acceptOwnershipHandover(other.actors.member, tenant.org.id),
      declineOwnershipHandover(other.actors.member, tenant.org.id),
      cancelOwnershipHandover(other.actors.owner, tenant.org.id),
      getPendingOwnershipHandover(other.actors.owner, tenant.org.id),
    ];
    for (const attempt of foreign) {
      await expect(attempt).rejects.toBeInstanceOf(TenantScopeError);
    }
  });
});

describe("answering an offer", () => {
  it("lets only the offered member accept or decline", async () => {
    const tenant = await createTenant("handover-addressee");
    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member);

    for (const role of ["owner", "admin", "viewer"] as const) {
      expect(
        await refusal(acceptOwnershipHandover(tenant.actors[role], tenant.org.id)),
        role,
      ).toBe("nothing_pending");
      expect(
        await refusal(declineOwnershipHandover(tenant.actors[role], tenant.org.id)),
        role,
      ).toBe("nothing_pending");
    }

    const declined = await declineOwnershipHandover(tenant.actors.member, tenant.org.id);
    expect(declined.status).toBe("declined");
    expect(declined.resolvedAt).toEqual(expect.any(String));
    expect(await roleOf(tenant, "member")).toBe("member");

    await expect(
      getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).resolves.toBeNull();
    await expect(
      initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).resolves.toMatchObject({ status: "pending" });
  });

  it("transfers ownership on acceptance, announcing every change", async () => {
    const tenant = await createTenant("handover-accept");
    const detachActivity = registerActivityListeners();
    detachers.push(detachActivity);

    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.member);

    const roleChanges = capture("member.role_changed");
    const transfers = capture("organization.ownership_transferred");

    const org = await acceptOwnershipHandover(tenant.actors.member, tenant.org.id);

    expect(org.id).toBe(tenant.org.id);
    expect(org.ownerId).toBe(tenant.userIds.member);
    expect((await orgRepo.findOrgById(tenant.org.id))?.ownerId).toBe(tenant.userIds.member);
    expect(await roleOf(tenant, "member")).toBe("owner");
    expect(await roleOf(tenant, "owner")).toBe("admin");

    expect(roleChanges).toHaveLength(2);
    expect(roleChanges).toEqual(
      expect.arrayContaining([
        expect.objectContaining({
          orgId: tenant.org.id,
          actorId: tenant.userIds.member,
          memberId: await memberIdOf(tenant, "member"),
          from: "member",
          to: "owner",
        }),
        expect.objectContaining({
          orgId: tenant.org.id,
          actorId: tenant.userIds.member,
          memberId: await memberIdOf(tenant, "owner"),
          from: "owner",
          to: "admin",
        }),
      ]),
    );
    expect(transfers).toEqual([
      expect.objectContaining({
        orgId: tenant.org.id,
        actorId: tenant.userIds.member,
        fromUserId: tenant.userIds.owner,
        toUserId: tenant.userIds.member,
      }),
    ]);

    const audit = await listActivity(
      { ...tenant.actors.member, role: "owner" },
      {
        orgId: tenant.org.id,
        action: ["organization.ownership_transferred"],
        limit: 25,
        cursor: null,
      },
    );
    expect(audit.items).toEqual([
      expect.objectContaining({
        action: "organization.ownership_transferred",
        actorId: tenant.userIds.member,
        subjectKind: "organization",
        subjectId: tenant.org.id,
        metadata: { fromUserId: tenant.userIds.owner, toUserId: tenant.userIds.member },
      }),
    ]);

    await expect(
      getPendingOwnershipHandover(tenant.actors.owner, tenant.org.id),
    ).resolves.toBeNull();
    expect(await refusal(acceptOwnershipHandover(tenant.actors.member, tenant.org.id))).toBe(
      "nothing_pending",
    );
  });

  it("only demotes the previous owner when the new one already held the owner role", async () => {
    const tenant = await createTenant("handover-co-owner");
    const coOwner = await promoteAdminToOwner(tenant);
    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.admin);

    const roleChanges = capture("member.role_changed");
    await acceptOwnershipHandover(coOwner, tenant.org.id);

    expect(roleChanges).toEqual([
      expect.objectContaining({
        memberId: await memberIdOf(tenant, "owner"),
        from: "owner",
        to: "admin",
      }),
    ]);
    expect(await roleOf(tenant, "admin")).toBe("owner");
    expect(await roleOf(tenant, "owner")).toBe("admin");
  });

  it("makes everything that follows the owner follow the new one", async () => {
    const tenant = await createTenant("handover-consequences");
    await initiateOwnershipHandover(tenant.actors.owner, tenant.org.id, tenant.userIds.admin);
    await acceptOwnershipHandover(tenant.actors.admin, tenant.org.id);

    const newOwner = await memberService.resolveActor(tenant.userIds.admin, tenant.org.id);
    const previousOwner = await memberService.resolveActor(tenant.userIds.owner, tenant.org.id);
    if (!newOwner || !previousOwner) throw new Error("actors missing");
    expect(previousOwner.role).toBe("admin");

    await emit("member.joined", {
      orgId: tenant.org.id,
      actorId: tenant.userIds.viewer,
      occurredAt: tenant.org.createdAt,
      memberId: await memberIdOf(tenant, "viewer"),
      userId: tenant.userIds.viewer,
      role: "viewer",
    });
    for (const [actor, expected] of [
      [newOwner, 1],
      [previousOwner, 0],
    ] as const) {
      const alerts = await listNotifications(actor, {
        orgId: tenant.org.id,
        recipientId: actor.userId,
        unreadOnly: false,
        kind: ["member_joined"],
        limit: 25,
        cursor: null,
      });
      expect(alerts.total).toBe(expected);
    }

    const plan = { orgId: tenant.org.id, plan: "enterprise", interval: "monthly" } as const;
    for (const stale of [previousOwner, tenant.actors.owner]) {
      await expect(billingService.changePlan(stale, plan)).rejects.toBeInstanceOf(
        PermissionDeniedError,
      );
    }
    await expect(billingService.changePlan(newOwner, plan)).resolves.toMatchObject({
      plan: "enterprise",
    });

    const removed = await memberService.removeMember(newOwner, {
      orgId: tenant.org.id,
      memberId: await memberIdOf(tenant, "owner"),
    });
    expect(removed.archivedAt).not.toBeNull();
  });
});

describe("lapsing", () => {
  it("can be acted on until, but not from, seven days after it was made", async () => {
    const tenant = await createTenant("handover-lapse-edge");
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-05-01T12:00:00.000Z"));

    const handover = await initiateOwnershipHandover(
      tenant.actors.owner,
      tenant.org.id,
      tenant.userIds.member,
    );
    const lapsesAt = Date.parse(handover.createdAt) + SEVEN_DAYS_MS;

    vi.setSystemTime(lapsesAt - 1);
    await expect(
      getPendingOwnershipHandover(tenant.actors.admin, tenant.org.id),
    ).resolves.toMatchObject({ id: handover.id });
    await expect(
      acceptOwnershipHandover(tenant.actors.member, tenant.org.id),
    ).resolves.toMatchObject({ ownerId: tenant.userIds.member });
  });

  it("refuses a lapsed offer as expired and stops counting it as open", async () => {
    const tenant = await createTenant("handover-lapse");
    vi.useFakeTimers({ toFake: ["Date"] });
